    static final class Fixture {
        final Snapshot x,a,b,d;final Origin own,foreign;
        final ContextUniversalFrozenBranch.Limits limits=ContextUniversalGroupedRoundsRunner.limits(16);
        Fixture()throws Exception {
            x=bind(true,"!$u seed(u,1); !@u @v seed(u,1)&&b(u,v)->r(u,v); !@v all(v);");
            a=bind(false,"!$u seed(u,1);");
            b=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2);");
            d=bind(false,"!@u @v b(u,v);");Packet common=ContextPrivateWitnessPoolRunner.common(x);own=ContextUniversalPrivateSymbolicMatrix.origins(common,"seed").iterator().next();PrivatePool pool=ContextWitnessResultTransport.privatePoolSigned(common,x,a,WORK);foreign=ContextUniversalPrivateSymbolicMatrix.origins(pool.local,"seed").stream().filter(o->!o.source.localX).findFirst().get();
            require(!own.equals(foreign)&&own.binder==foreign.binder&&own.source.localX&&!foreign.source.localX,"same binder0 in X and A remains two actual rigid Origins");
        }
        Set<Source> sources(Source... s){return ContextUniversalSourceAlternativesMatrix.sources(s);}
        void initial(Entry e){
            require(e.common.items.size()==1&&ContextUniversalPrivateSymbolicMatrix.origins(e.common,"seed").equals(Collections.singleton(own))&&e.common.items.get(0).proofs.size()==1&&e.common.items.get(0).proofs.get(0).depth==0&&e.common.items.get(0).proofs.get(0).sources.equals(sources(x.primary.get(0).source)),"actual whole primary X Origin seed, no private A seed imported");
            require(e.pools.size()==1&&e.pools.get(Cut.of(a)).sources.equals(sources(a.primary.get(0).source)),"A original private witness pool separate from primary X common");
            Map<Set<Source>,Integer> expectedUnits=new HashMap<>();expectedUnits.put(sources(x.primary.get(2).source),0);expectedUnits.put(sources(x.primary.get(0).source,x.primary.get(1).source,b.primary.get(0).source),2);expectedUnits.put(sources(x.primary.get(0).source,x.primary.get(1).source,d.primary.get(0).source),2);List<Support> units=new ArrayList<>();
            for(ContextUniversalSignedUnitExchange.Unit unit:e.units.units){units.add(unit.support);require(unit.owner.proofs.contains(unit.proof)&&unit.clause==unit.proof.clause&&unit.support==unit.proof.support&&unit.clause.variables.size()==1,"actual owning initial unit proof; one free variable retained");String predicate=unit.clause.literals.get(0).predicate;if(predicate.equals("all"))require(unit.clause.origins.isEmpty()&&unit.support.depth==0,"universal all remains variable, not a private parameter");else require(predicate.equals("r")&&unit.clause.origins.equals(Collections.singleton(own))&&unit.support.depth==2,"initial residual r has original X Origin AND distinct free variable");}
            require(e.units.units.size()==3&&ContextUniversalSourceAlternativesMatrix.supports(units).equals(expectedUnits),"EXACT three nonempty initial units, independent B/D Source alternatives preserved");
            Map<Set<Source>,Integer> compounds=new HashMap<>();compounds.put(sources(x.primary.get(1).source),0);compounds.put(sources(x.primary.get(0).source,x.primary.get(1).source),1);compounds.put(sources(a.primary.get(0).source,x.primary.get(1).source),1);compounds.put(sources(b.primary.get(0).source,x.primary.get(1).source),1);compounds.put(sources(d.primary.get(0).source,x.primary.get(1).source),1);compounds.put(sources(x.primary.get(0).source,x.primary.get(1).source,b.primary.get(0).source,b.primary.get(1).source),3);boolean grouped=e.foreign.stream().anyMatch(cut->cut.members.contains(b)&&cut.members.contains(d));if(grouped)compounds.put(sources(x.primary.get(0).source,x.primary.get(1).source,d.primary.get(0).source,b.primary.get(1).source),3);List<Support> proofs=new ArrayList<>();Set<Origin> origins=new HashSet<>();
            for(ContextUniversalCompoundExchange.ResidualProof p:e.compounds.clauses){proofs.add(p.support);origins.addAll(p.clause.origins);require(p.owner.proofs.contains(p.proof)&&p.support==p.proof.support&&p.clause==p.proof.clause,"actual original initial compound proof ownership");if(p.support.sources.size()==1)require(p.clause.literals.size()==3&&p.clause.variables.size()==2&&p.clause.origins.isEmpty()&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"seed",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"b",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"r",true),"exact original compound schema");else if(p.support.sources.equals(sources(x.primary.get(1).source,b.primary.get(0).source))||p.support.sources.equals(sources(x.primary.get(1).source,d.primary.get(0).source)))require(p.clause.literals.size()==2&&p.clause.variables.size()==2&&p.clause.origins.isEmpty()&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"seed",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"r",true),"exact free-variable donor residual");else if(p.support.sources.size()==2)require(p.clause.literals.size()==2&&p.clause.variables.size()==1&&p.clause.origins.equals(Collections.singleton(p.support.sources.contains(a.primary.get(0).source)?foreign:own))&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"b",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"r",true),"exact primary/private Origin residual");else require(p.clause.literals.size()==2&&p.clause.variables.size()==1&&p.clause.origins.equals(Collections.singleton(own))&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"need",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"s",true),"exact initial consumer residual on primary X Origin");}
            require(e.compounds.clauses.size()==(grouped?7:6)&&ContextUniversalSourceAlternativesMatrix.supports(proofs).equals(compounds)&&origins.equals(new HashSet<>(Arrays.asList(own,foreign))),"EXACT original initial compound Source minima and both distinct Origin identities");
        }
        void products(org.kanger.ContextUniversalGroupedRounds.Result r){
            require(r.output.packet.items.size()==3&&ContextUniversalPrivateSymbolicMatrix.origins(r.output.packet,"seed").equals(Collections.singleton(own))&&ContextUniversalPrivateSymbolicMatrix.origins(r.output.packet,"s").equals(new HashSet<>(Arrays.asList(own,foreign))),"only original X seed plus two Origin-valued s facts are shared");
            int seen=0;for(Item i:r.output.packet.items)if(i.atom.predicate.equals("s")){Origin origin=i.atom.arguments.get(0).origin;require(i.atom.positive&&origin!=null&&i.atom.arguments.get(1).origin==null&&i.atom.arguments.get(1).value.semanticallyEquals(b.primary.get(2).clauses.get(0).literals.get(0).arguments.get(0).value),"actual need2 result, no arbitrary value or Origin/value alias");Map<Set<Source>,Integer> expected=new HashMap<>();for(Snapshot donor:Arrays.asList(b,d))expected.put(sources(origin.source,x.primary.get(1).source,donor.primary.get(0).source,b.primary.get(1).source,b.primary.get(2).source),3);require(i.proofs.size()==2&&ContextUniversalSourceAlternativesMatrix.supports(i.proofs).equals(expected),"EXACT two independent donor alternatives at grade3 for EACH actual Origin");++seen;}
            require(seen==2&&!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"all")&&!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"b")&&!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"r")&&!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"need"),"universal all/r are not fabricated fixed facts; raw foreign b/need never shared");
            for(String predicate:Arrays.asList("all","r"))require(r.symbolicOutput.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals(predicate)),"nonempty symbolic carrier survives: "+predicate);
        }
    }
    static void positive()throws Exception {
        Fixture f=new Fixture();List<List<Snapshot>> orders=new ArrayList<>(ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.d)));for(List<Snapshot> members:Arrays.asList(Arrays.asList(f.b,f.d),Arrays.asList(f.d,f.b))){Snapshot group=ContextProductionNativeBinding.trusted("primary-x-native",members,WORK);orders.add(Arrays.asList(f.a,group));orders.add(Arrays.asList(group,f.a));}
        org.kanger.ContextUniversalGroupedRounds.Result previous=null;for(List<Snapshot> order:orders){Entry e=ContextUniversalInitialEntryAuditMatrix.entry(f.x,order,f.limits);f.initial(e);org.kanger.ContextUniversalGroupedRounds.Result r=ContextUniversalInitialEntryAuditMatrix.handed(e,f.limits);f.products(r);if(previous!=null)same(previous,r);previous=r;}
        require(orders.size()==10,"all six independent and four trusted primary-X handoffs");System.out.println("INITIAL_NATIVE_BOUNDARY_POSITIVE independentOrders=6 trustedVariants=4 initialUnits=3 initialCompoundsIndependent=6 trusted=7 primaryAndForeignBinder0Distinct=true exactFinalSourceAlternatives=4");
    }
    static org.kanger.ContextUniversalInitialEntry.Result assemble(Snapshot x,List<Snapshot> cuts){return ContextUniversalInitialEntry.assemble(x,cuts,ContextUniversalGroupedRoundsRunner.limits(16),4096);}
    static void initialRefuted(org.kanger.ContextUniversalInitialEntry.Result r,Cut cut,boolean own,Set<Source> expected){require(r.status==ContextUniversalInitialEntry.Status.REFUTED&&r.entry==null&&r.refutations.keySet().equals(Collections.singleton(cut)),"actual closed initial contradiction exposes evidence but NO Entry");org.kanger.ContextUniversalInitialEntry.Rejection rejection=r.refutations.get(cut);require(rejection.xRefuted==own&&rejection.foreignRefuted!=own&&rejection.proofs.size()==1,"exact initial rejection classification");org.kanger.ContextUniversalFrozenConstraints.Proof proof=rejection.proofs.get(0);require(proof.clause==null&&proof.support.depth==1&&proof.support.sources.equals(expected),"exact empty1 original Source evidence, no unrelated X anchor mixed in");ContextUniversalInitialEntryAuditMatrix.no(ContextUniversalInitialEntryAuditMatrix.inspect(r.entry,ContextUniversalGroupedRoundsRunner.limits(16),WORK),"REFUTED is not a READY receipt");}
    static void rejection()throws Exception {
        Snapshot x=bind(true,"!$u seed(u,1); !@v all(v);"),negative=bind(false,"!@u ~seed(u,1);");initialRefuted(assemble(x,Collections.singletonList(negative)),Cut.of(negative),true,ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(0).source,negative.primary.get(0).source));
        Snapshot anchor=bind(true,"!anchor(1);"),yes=bind(false,"!p(1);"),no=bind(false,"!~p(1);");ContextUniversalFrozenBranch.Limits l=ContextUniversalGroupedRoundsRunner.limits(16);
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(yes,no),Arrays.asList(no,yes))){Entry e=ContextUniversalInitialEntryAuditMatrix.entry(anchor,order,l);org.kanger.ContextUniversalGroupedRounds.Result stable=ContextUniversalInitialEntryAuditMatrix.handed(e,l);require(stable.completedRounds==1&&stable.output.packet.items.size()==1&&stable.symbolicOutput.units.isEmpty()&&stable.compoundOutput.clauses.isEmpty(),"independent sibling collision never manufactured under unrelated X anchor");Snapshot group=ContextProductionNativeBinding.trusted("initial-native-refutation",order,WORK);initialRefuted(assemble(anchor,Collections.singletonList(group)),Cut.of(group),false,ContextUniversalSourceAlternativesMatrix.sources(yes.primary.get(0).source,no.primary.get(0).source));}
        for(String text:Arrays.asList("!@u (seed(u,1)&&c(u)->s(u))&&(left(u)||right(u));","!$u $v pair(u,v);")){Snapshot bad=bind(false,text);for(List<Snapshot> order:Arrays.asList(Arrays.asList(negative,bad),Arrays.asList(bad,negative)))ContextUniversalInitialEntryMatrix.incomplete(assemble(x,order),"later unsupported/unready cut hides earlier actual X-Origin contradiction");}
        for(List<Snapshot> members:Arrays.asList(Arrays.asList(yes,no),Arrays.asList(no,yes))){Snapshot group=ContextProductionNativeBinding.trusted("early-refuted",members,WORK);Snapshot bad=bind(false,"!left(1)||right(1);");ContextUniversalInitialEntryMatrix.incomplete(assemble(anchor,Arrays.asList(group,bad)),"later whole-row refusal suppresses foreign-only trusted contradiction");}
        delayed();System.out.println("INITIAL_NATIVE_BOUNDARY_REJECTIONS primaryOriginEmpty1=true independentOpinionsStable=2 trustedForeignOnly=2 delayedCheckedOrders=6 laterRefusalAtomic=true");
    }
    static void delayed()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u);"),rule=bind(false,"!@u p(u)&&b(u)->r(u);"),donor=bind(false,"!b(1);"),opposite=bind(false,"!~r(1);");ContextUniversalFrozenBranch.Limits l=ContextUniversalGroupedRoundsRunner.limits(16);Set<Source> expected=ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(1).source,rule.primary.get(0).source,donor.primary.get(0).source,opposite.primary.get(0).source);
        for(List<Snapshot> order:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(rule,donor,opposite))){Entry e=ContextUniversalInitialEntryAuditMatrix.entry(x,order,l);require(!e.units.units.isEmpty()&&e.units.units.stream().allMatch(u->u.clause.literals.get(0).predicate.equals("p")&&u.support.depth==0),"actual universal p initial symbolic input, not invented fixed p");Receipt receipt=ContextUniversalInitialEntryAuditMatrix.yes(ContextUniversalInitialEntryAuditMatrix.inspect(e,l,WORK));Frame f=ContextUniversalInitialEntryMatrix.frame(e);org.kanger.ContextUniversalGroupedRounds.SessionRun one=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,l,f.local,1,WORK,4096);incomplete(one,"one progressing barrier cannot issue stable or rejection prefix");org.kanger.ContextUniversalGroupedRounds.SessionRun full=ContextUniversalGroupedRounds.runInitialWithValidationReuse(receipt,l,f.local,8,WORK,4096);ContextUniversalContinuationRefutationRunner.reject(f,full,2);require(full.result.refutations.keySet().equals(new HashSet<>(Arrays.asList(Cut.of(donor),Cut.of(opposite)))),"B and opposite cuts BOTH refute on NEXT barrier, including actual signed contraposition");for(org.kanger.ContextUniversalGroupedRounds.Refutation ref:full.result.refutations.values()){require(ref.proofs.size()==1,"exact one earliest empty alternative");for(org.kanger.ContextUniversalFrozenConstraints.Proof p:ref.proofs)require(p.clause==null&&p.support.depth==2&&p.support.sources.equals(expected),"checked initial p handoff preserves exact four-Source empty2");}
            Set<org.kanger.ContextUniversalFrozenConstraints.Proof> ancestry=Collections.newSetFromMap(new IdentityHashMap<org.kanger.ContextUniversalFrozenConstraints.Proof,Boolean>());ContextUniversalPrivateSymbolicMatrix.ancestry(full.result.refutations.get(Cut.of(donor)).proofs.get(0),ancestry);Set<Source> negativeSources=new HashSet<>(expected);negativeSources.remove(donor.primary.get(0).source);require(ancestry.stream().anyMatch(p->p.clause!=null&&p.clause.literals.size()==1&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"b",false)&&p.support.depth==1&&p.support.sources.equals(negativeSources)),"actual donor rejection contains checked negative-b1 with exact three Source ancestors");
            org.kanger.ContextUniversalGroupedRounds.Result ordinary=ContextUniversalGroupedRounds.run(e.x,e.foreign,e.common,e.pools,e.units,e.compounds,l,f.local,8,WORK);require(ordinary.status==org.kanger.ContextUniversalGroupedRounds.Status.REFUTED&&ordinary.refutations.keySet().equals(full.result.refutations.keySet()),"fresh ordinary controller reproduces rejection cut inventory");for(org.kanger.ContextUniversalGroupedRounds.Refutation ref:ordinary.refutations.values())require(ContextUniversalSignedAlternativesMatrix.empty(ref).equals(ContextUniversalSignedAlternativesMatrix.empty(full.result.refutations.get(ref.cut))),"ordinary semantic reference has same complete exact Source-depth empty inventory");
        }
    }
